static const char FILE_PAGE[] = "<!doctype html><html lang=\"zh-CN\"><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><title>IGW 双总线文件交换</title>\n<style>:root{font-family:system-ui,sans-serif;color:#17333e;background:#f1f5f7}body{margin:0}main{max-width:960px;margin:32px auto;padding:0 20px}header{padding:12px 0}h1{font-size:28px;margin:8px 0}h2{font-size:18px;margin-top:0}p{line-height:1.6}section{background:white;border:1px solid #d8e4e8;border-radius:12px;padding:22px;margin:16px 0}label{display:inline-block;margin:6px 20px 6px 0}button,select,input{font:inherit;border:1px solid #b8cbd1;border-radius:6px;padding:9px}button{background:#086879;color:white;cursor:pointer;margin:6px 8px 6px 0}button:disabled{opacity:.45;cursor:default}input[type=number]{width:140px}.note{font-size:14px;color:#526b76}#state{white-space:pre-wrap;background:#e9f4f5;border-radius:8px;padding:14px}.bad{color:#a62525}pre{font-size:13px;overflow-wrap:anywhere;white-space:pre-wrap}article{border-top:1px solid #d8e4e8;padding:16px 0}progress{width:100%;height:20px}#cancel{background:#904329}\n/* Same visual language as monitoring. Existing operations and API logic unchanged. */\n:root{font-family:system-ui,\"Microsoft YaHei\",sans-serif;color:#172c3c;background:#f2f5f7}html{scroll-behavior:smooth;scroll-padding-top:80px}main{max-width:1160px;margin:0 auto;padding:0 28px 48px}header{padding:34px 0 22px}header h1{font-size:30px;color:#12394a;letter-spacing:-.02em}header p{color:#587080}.brand-label,.eyebrow{font-size:11px;font-weight:800;letter-spacing:.08em;color:#087b75}.jumpnav{display:flex;gap:6px;align-items:center;flex-wrap:wrap;position:sticky;top:8px;z-index:4;background:#fff;border:1px solid #d9e3e8;box-shadow:0 4px 18px rgba(30,60,70,.07);padding:8px;border-radius:12px;margin-bottom:18px}.jumpnav span{font-size:12px;font-weight:700;color:#667d87;padding:0 9px}.jumpnav a{color:#365765;text-decoration:none;font-weight:650;font-size:13px;padding:7px 12px;border-radius:7px}.jumpnav a:hover,.jumpnav a:focus{background:#e6f3f1;color:#075d5c}section{border-radius:14px;border-color:#d9e3e8;box-shadow:0 3px 14px rgba(20,51,65,.035);padding:24px;margin:16px 0;scroll-margin-top:90px}h2{color:#173947;margin:4px 0 15px;font-size:20px}label{color:#385664;font-weight:600}button,select,input{border-radius:8px;border-color:#b9cbd2}select,input{background:#f9fbfc;color:#172c3c}input[type=file]{width:100%;box-sizing:border-box;background:#f9fbfc}button{background:#087e79;border-color:#087e79;font-weight:650;padding:10px 16px}button:hover:not(:disabled){background:#06635f}button:disabled{cursor:not-allowed}#cancel{background:#fff3ec;color:#974728;border-color:#e7c6b6}#refresh{background:#eef5f6;color:#244555;border-color:#c7d9df}.note{font-size:13px;color:#587080}#state{background:#e8f4f2;border:1px solid #cce5df;color:#235951}.bad#state{color:#a62525;background:#fff1ef;border-color:#efd4cf}.actions{display:grid;grid-template-columns:1fr 1fr;gap:18px}.actions section{margin:0;min-width:0}#results{margin-top:18px}article{padding:18px 0}progress{accent-color:#087e79}@media(max-width:800px){main{padding:0 16px 40px}.jumpnav{position:static}.actions{grid-template-columns:1fr}.actions section{margin:0}}\n</style>\n<main><header><span class=\"brand-label\">IGW / 文件服务</span><h1>双总线文件交换</h1><p>电脑通过以太网连接网关，选择 CAN 或 RS485 与设备交换文件。</p></header><nav class=\"jumpnav\" aria-label=\"页面功能导航\"><span>功能导航</span><a href=\"#target\">选择目标</a><a href=\"#send\">发送文件</a><a href=\"#receive\">取回文件</a><a href=\"#results\">进度与结果</a></nav>\n<section id=\"target\" class=\"target\"><span class=\"eyebrow\">第一步 / 选择目标</span><h2>选择总线和设备</h2><label>传输总线 <select id=\"bus\"><option value=\"can\">CAN · 500 kbit/s</option><option value=\"rs485\">RS485 · 9600 bit/s</option></select></label><label>设备 <select id=\"unit\"><option value=\"1\">逻辑设备 1</option><option value=\"2\">逻辑设备 2</option><option value=\"3\">设备 3 · Zynq（仅 RS485）</option></select></label><p class=\"note\">允许 CAN 设备 1 和 RS485 设备 3 两个文件任务同时进行；其他组合一次只能执行一个任务。设备 3 使用 Zynq 的 TF 卡。单文件最大 8 MiB，RS485 为 9600 bit/s，请先用 4096 字节测试。</p><div id=\"state\">正在连接网关…</div></section>\n<div class=\"actions\"><section id=\"send\"><span class=\"eyebrow\">第二步 / 主机 → 从机</span><h2>发送电脑文件</h2><input id=\"file\" type=\"file\"><p class=\"note\">下发后自动从所选总线独立读回并比较 SHA256。新文件完成 SD 校验后提交；未完成写入保留旧版。1 MiB 的 CAN 下发与读回实测合计约 3 分 9 秒。</p><button id=\"put\">下发并读回校验</button></section>\n<section id=\"receive\"><span class=\"eyebrow\">第二步 / 从机 → 主机</span><h2>取回设备文件</h2><button id=\"get\">取回设备现有文件</button><button id=\"pair\">并行取回设备 1 和 3 的现有文件</button><label>测试文件字节数 <input id=\"size\" type=\"number\" min=\"0\" max=\"8388608\" value=\"4096\"></label><button id=\"generate\">设备生成并取回</button><p class=\"note\">并行取回读取两个设备各自的现有文件，不更改设备上的文件；两个设备须已有文件。生成或下发文件会更新对应设备的文件槽。RS485 较慢，实际耗时以板上为准。</p></section>\n</div><section id=\"results\"><span class=\"eyebrow\">第三步 / 查看结果</span><h2>传输进度与结果</h2><button id=\"refresh\">刷新结果</button><button id=\"cancel\" disabled>停止全部传输</button><div id=\"jobs\"></div><p class=\"note\">关闭网页不会取消任务，重新打开可查看当前会话。停止按钮会停止全部进行中的任务；停止或失败后请保留日志并检查总线。成功文件可在此下载到电脑。退出主机服务时将证据复制到主机 SD 卡。</p></section></main>\n<script>\n'use strict';\nlet token='',busy=false,serverBusy=false,blocked=false,polling=false,remaining=16,running=[];const names=new Map(),el=id=>document.getElementById(id);\nfunction targetChanged(){const is3=el('unit').value==='3';if(is3)el('bus').value='rs485';el('bus').querySelector('option[value=can]').disabled=is3;controls();}\nel('unit').addEventListener('change',targetChanged);el('bus').addEventListener('change',controls);\nfunction status(text,bad=false){el('state').textContent=text;el('state').className=bad?'bad':'';}\nfunction canStart(bus,unit){if(!serverBusy)return true;if(running.length!==1)return false;const j=running[0];return (j.bus==='can'&&j.unit===1&&bus==='rs485'&&unit===3)||(j.bus==='rs485'&&j.unit===3&&bus==='can'&&unit===1);}\nfunction controls(){const allowed=canStart(el('bus').value,Number(el('unit').value));for(const id of ['put','get','generate'])el(id).disabled=busy||!allowed||blocked||!token||remaining<=0;el('pair').disabled=busy||serverBusy||blocked||!token||remaining<2;el('refresh').disabled=busy||!token;el('cancel').disabled=busy||!serverBusy||!token;for(const id of ['bus','unit','file','size'])el(id).disabled=busy;}\nasync function jsonResponse(r){let v;try{v=await r.json();}catch{throw Error('网关响应不完整，请刷新结果并保留日志。');}if(!r.ok||v.ok===false)throw Error(v.error||'请求失败');return v;}\nasync function download(job){if(busy||serverBusy)return;busy=true;controls();try{const r=await fetch('/api/download?id='+encodeURIComponent(job.job_id),{headers:{'X-IGW-Token':token},cache:'no-store'});if(!r.ok){await jsonResponse(r);return;}const blob=await r.blob();if(blob.size!==job.bytes)throw Error('下载长度不一致');if(globalThis.crypto&&crypto.subtle){const hash=await crypto.subtle.digest('SHA-256',await blob.arrayBuffer());const hex=Array.from(new Uint8Array(hash),v=>v.toString(16).padStart(2,'0')).join('');if(hex!==job.sha256)throw Error('电脑端 SHA256 不一致');}const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=names.get(job.job_id)||('device'+job.unit+'-'+job.job_id.slice(0,8)+'.bin');a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);status('已下载 '+job.bytes+' 字节到电脑。');}catch(e){status(e.message,true);}finally{busy=false;controls();}}\nconst phaseNames={starting:'准备',put:'下发',readback:'独立读回',get:'取回',generate:'生成并取回',verify:'校验',complete:'校验通过',failed:'失败'};\nasync function refresh(){if(polling||!token)return;polling=true;try{const d=await jsonResponse(await fetch('/api/jobs',{headers:{'X-IGW-Token':token},cache:'no-store'}));blocked=d.blocked;serverBusy=d.busy;running=d.jobs.filter(j=>!j.done);remaining=16-d.jobs.length;el('jobs').replaceChildren();for(const j of d.jobs.slice().reverse()){const a=document.createElement('article'),title=document.createElement('strong'),detail=document.createElement('pre');title.textContent=j.bus.toUpperCase()+' · 设备 '+j.unit+' · '+j.operation+' · '+(phaseNames[j.phase]||j.phase);detail.textContent=(j.done?j.bytes+' 字节':j.progress_bytes+' / '+j.total_bytes+' 字节')+'\\nSHA256: '+(j.sha256||'完成后显示')+'\\n任务: '+j.job_id;a.append(title,detail);if(!j.done){const p=document.createElement('progress');p.max=j.total_bytes||1;p.value=j.progress_bytes;a.append(p);}if(j.ok){const b=document.createElement('button');b.textContent='下载已校验文件';b.disabled=serverBusy;b.onclick=()=>download(j);a.append(b);}el('jobs').append(a);}if(blocked)status('本会话有停止或失败的任务。请保留日志并检查总线；其他进行中的任务可继续。',true);else if(serverBusy)status('正在执行 '+running.length+' 个任务。可并行的组合为 CAN 设备 1 与 RS485 设备 3。');else if(d.jobs.length)status('当前无传输任务。校验通过的文件可下载，剩余任务名额 '+remaining+'。');}finally{polling=false;controls();}}\nasync function transfer(op){if(busy||blocked||!canStart(el('bus').value,Number(el('unit').value)))return;busy=true;controls();let body=new Uint8Array(0),size=0,name='';const unit=Number(el('unit').value),bus=el('bus').value;try{if(unit===3&&bus!=='rs485')throw Error('设备 3 仅支持 RS485');if(op==='put'){const f=el('file').files[0];if(!f)throw Error('请先选择电脑文件');if(f.size>8388608)throw Error('文件不能超过 8388608 字节（8 MiB）');body=await f.arrayBuffer();size=f.size;name=f.name||'';}else if(op==='generate'){size=Number(el('size').value);if(!Number.isInteger(size)||size<0||size>8388608)throw Error('字节数需在 0～8388608 范围内');}status('正在提交任务…');const j=await jsonResponse(await fetch('/api/file?op='+op+'&unit='+unit+'&size='+size+'&bus='+bus,{method:'POST',headers:{'X-IGW-Token':token,'Content-Type':'application/octet-stream'},body}));if(name)names.set(j.job_id,name);serverBusy=true;await refresh();}catch(e){status(e.message,true);}finally{busy=false;controls();}}\nasync function pairGet(){if(busy||serverBusy||blocked||remaining<2)return;busy=true;controls();try{for(const [bus,unit] of [['can',1],['rs485',3]]){await jsonResponse(await fetch('/api/file?op=get&unit='+unit+'&size=0&bus='+bus,{method:'POST',headers:{'X-IGW-Token':token},body:new Uint8Array(0)}));serverBusy=true;}await refresh();}catch(e){await refresh().catch(()=>{});status('并行提交未全部成功，请查看任务列表和日志：'+e.message,true);}finally{busy=false;controls();}}\nel('put').onclick=()=>transfer('put');el('get').onclick=()=>transfer('get');el('pair').onclick=pairGet;el('generate').onclick=()=>transfer('generate');el('refresh').onclick=()=>refresh().catch(e=>status(e.message,true));el('cancel').onclick=async()=>{if(busy||!serverBusy)return;busy=true;controls();try{await jsonResponse(await fetch('/api/cancel',{method:'POST',headers:{'X-IGW-Token':token},body:new Uint8Array(0)}));blocked=true;status('全部传输的停止请求已提交，等待总线清理；请保留日志。',true);}catch(e){status(e.message,true);}finally{busy=false;controls();}};\ntargetChanged();(async()=>{try{const s=await jsonResponse(await fetch('/api/session',{cache:'no-store'}));token=s.token;blocked=s.blocked;serverBusy=s.busy;status('网关已连接。请选择总线、设备和文件。');await refresh();}catch(e){status(e.message,true);}controls();})();\nsetInterval(()=>{if(token&&!busy)refresh().catch(e=>status('暂时无法刷新：'+e.message,true));},1000);\n</script></html>\n";
